INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q111032472', '1819 Singapore Treaty', 'The signing of the Treaty of Singapore on 6 February 1819 is officially recognised as the founding of modern-day Singapore. The Treaty allowed the British East India Company to open up a trading post in Singapore, marking the beginning of a British settlement.', 1819, 2, 6, NULL, NULL, NULL, 'day', '6 February 1819', 37, 'https://en.wikipedia.org/wiki/1819_Singapore_Treaty'),
  ('Q296754', 'Battle of Singapore', 'Singapore was captured from the British by the Empire of Japan in February 1942 during the Second World War. The Fall or Battle of Singapore took place in the South–East Asian theatre of the Pacific War, with fighting lasting from 8 to 15 February 1942.', 1942, 2, 8, 1942, 2, 15, 'day', '8 February 1942 – 15 February 1942', 72, 'https://en.wikipedia.org/wiki/Fall_of_Singapore'),
  ('Q632926', 'Battle of Kranji', 'The Battle of Kranji was the second stage of the Empire of Japan''s plan for the invasion of Singapore during the Second World War. On 9 February 1942 the Imperial Japanese Army assaulted the north-western front of Singapore, capital of the Straits Settlements.', 1942, 2, 9, 1942, 2, 10, 'day', '9 February 1942 – 10 February 1942', 41, 'https://en.wikipedia.org/wiki/Battle_of_Kranji'),
  ('Q4208426', 'Battle of Pasir Panjang', 'The Battle of Pasir Panjang, which took place between 13 and 15 February 1942, was part of the final stage of the Empire of Japan''s invasion of Singapore during World War II. The battle was initiated upon the advancement of elite Imperial Japanese Army forces towards Pasir Panjang Ridge on 13 February. 13,000 Japanese troops had made an amphibious landing in northwestern Singapore near Sarimbun (see Battle of Sarimbun Beach) and had started to advance south towards Pasir Panjang.', 1942, 2, 15, 1942, 2, 14, 'day', '15 February 1942 – 14 February 1942', 34, 'https://en.wikipedia.org/wiki/Battle_of_Pasir_Panjang'),
  ('Q569689', 'Bombing of Singapore', 'The Bombing of Singapore (1944–1945) was a military campaign conducted by the Allied air forces during World War II. United States Army Air Forces (USAAF) long-range bomber units conducted 11 air raids on Japanese-occupied Singapore between November 1944 and March 1945. Most of these raids targeted the island''s naval base and dockyard facilities, and minelaying missions were conducted in nearby waters.', 1944, 11, 5, 1945, 5, 24, 'day', '5 November 1944 – 24 May 1945', 58, 'https://en.wikipedia.org/wiki/Bombing_of_Singapore_(1944%E2%80%931945)'),
  ('Q15991222', 'Independence of Singapore Agreement 1965', 'The Independence of Singapore Agreement 1965 was a pivotal agreement concluded between the governments of Malaysia and Singapore on 7 August 1965. It provided the legal and constitutional framework for Singapore''s formal secession from Malaysia, wherein it ceased to be a constituent state and assumed the status of an independent and sovereign nation.', 1965, 8, 7, NULL, NULL, NULL, 'day', '7 August 1965', 48, 'https://en.wikipedia.org/wiki/Independence_of_Singapore_Agreement_1965'),
  ('Q16156031', '1969 race riots of Singapore', 'The 1969 race riots of Singapore were communal disturbances and racial conflicts between the Malay and Chinese communities in Singapore. It lasted for seven days from 31 May to 6 June 1969.', 1969, 5, 31, 1969, 6, 6, 'day', '31 May 1969 – 6 June 1969', 45, 'https://en.wikipedia.org/wiki/1969_race_riots_of_Singapore'),
  ('Q796498', 'Third Indochina War', 'The Third Indochina War was a series of interconnected military conflicts among the various communist factions over strategic influence in mainland Southeast Asia after communist victory in South Vietnam, Laos, and Cambodia in 1975. The conflict primarily started due to continued raids and incursions by the Khmer Rouge into Vietnamese territory that they sought to retake.', 1975, 5, 1, 1991, 10, 23, 'day', '1 May 1975 – 23 October 1991', 53, 'https://en.wikipedia.org/wiki/Third_Indochina_War'),
  ('Q7523142', 'Singapore Treaty on the Law of Trademarks', 'The Singapore Treaty on the Law of Trademarks is a treaty adopted by the World Intellectual Property Organization in Singapore on 28 March 2006. It entered into force on 16 March 2009, following the ratification or accession of ten countries, namely Singapore, Switzerland, Bulgaria, Romania, Denmark, Latvia, Kyrgyzstan, United States, Moldova, and Australia.', 2006, 3, 28, NULL, NULL, NULL, 'day', '28 March 2006', 43, 'https://en.wikipedia.org/wiki/Singapore_Treaty_on_the_Law_of_Trademarks'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic');

